#[derive(Default)]
struct NonFusedIterator {
    state: i32,
}

impl Iterator for NonFusedIterator {
    type Item = i32;

    fn next(&mut self) -> Option<i32> {
        let val = self.state;
        self.state = self.state + 1;

        // Skip every 5th number
        if (val + 1) % 5 == 0 {
            None
        } else {
            Some(val)
        }
    }
}


